import{_ as l,l as s,o as a,c as i,v as t,p as d,x as r,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"步长与流预取器","description":"","frontmatter":{"title":"步长与流预取器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stride-stream-prefetch.md","filePath":"cs/stride-stream-prefetch.md","lastUpdated":1789023840000}'),h={name:"cs/stride-stream-prefetch.md"};function m(f,e,_,P,E,A){const o=s("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="步长与流预取器" tabindex="-1">步长与流预取器 <a class="header-anchor" href="#步长与流预取器" aria-label="Permalink to &quot;步长与流预取器&quot;">​</a></h1><div class="epigraph"><p>连续缺失若地址相差固定块距，就按该距向前发；流缓冲把预取与 L1 隔开，避免直接映射被未来块踢伤当前行。</p><footer>—— 据 Jouppi, ISCA 1990；Baer and Chen, An Effective On-Chip Preloading Scheme, ISCA 1991 整理</footer></div><p><a href="/cs/mlp-memory-parallelism">上一课</a> 要飞行中的请求。<a href="/cs/cache-prefetch">主干预取课</a> 已给出直觉。本课在进阶课序里把<strong>步长预测与流预取器</strong>写具体：如何检出 \\(\\Delta\\)，发到哪一层，和 <a href="/cs/mshr">MSHR</a> 怎么分账。不重讲强制缺失的定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数组 <code>a[i]</code>、矩阵行、包描述符环：缺失地址呈 \\(b, b+\\Delta, b+2\\Delta\\)。需求 load 才去 L2/DRAM 则 MLP 有，但第一条仍然付满延迟。缺口不是牺牲缓存（那是过去的受害者），而是<strong>为每条流维持一个游标，提前 \\(k\\) 块发出读</strong>。</p><p><span class="marginnote">Baer–Chen 在 TLB/表里记上一地址与步长。Jouppi 的 stream buffer 是 FIFO：预取进缓冲，CPU 命中再提升。现代核在 L1/L2 各有预取器，L2 的流更长。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按 load PC（或页）记录上次缺失地址。若新缺失 − 上次 = \\(\\Delta\\)（块对齐），则确认步长，向 \\(addr + k\\Delta\\) 发预取，\\(k\\) 为距离。多流：多组寄存器，按 PC 分配。页边界停止或换 \\(\\Delta\\)。</p>',8)),(a(),d(c,null,{default:r(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E9%9C%80%E6%B1%82%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20STR%5B%22%E6%8C%89%20PC%20%E6%9B%B4%E6%96%B0%E6%AD%A5%E9%95%BF%22%5D%0A%20%20STR%20--%3E%20PF%5B%22%E5%90%91%20addr%2Bk%CE%94%20%E5%8F%91%E9%A2%84%E5%8F%96%22%5D%0A%20%20PF%20--%3E%20MSHR%5B%22%E5%8D%A0%E7%94%A8%20MSHR%22%5D%0A%20%20PF%20--%3E%20BUF%5B%22%E5%A1%AB%20L2%20%E6%88%96%E6%B5%81%E7%BC%93%E5%86%B2%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>软件预取指令是同一接口的显式版：地址由编译器算，失败不得 trap。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预取成功时，强制缺失的有效延迟下降，MLP 看起来更高。\\(\\Delta=0\\) 或随机 PC 不要训练。间接数组 <code>a[b[i]]</code> 步长在 <code>b</code> 上不在 <code>a</code> 上，简单步长器失效——那是相关预取/指针预取，本课不展开。</p><p>与 <a href="/cs/rrip-dead-block">RRIP</a>：预取填入应插成较远 RRPV，否则扫描预取变成合法的污染。下一课专讲时机与污染。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GPU 合并访存当步长器。也不把预取距离调参写成操作系统 API。指令预取（I-stream）类似但用取指 PC，与分支预测交互，容易在跳转后作废。</p><p>后课默认：固定 \\(\\Delta\\) 的流可以硬件预取。发早了、发错了会占带宽并踢热块，需要反馈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>步长器按 PC 学习 \\(\\Delta\\)，流缓冲隔离预取与 L1。</li><li>预取占用与需求 miss 同一套 MSHR。</li><li>时机与污染的反馈是下一课。</li><li>出处：Jouppi, <em>ISCA</em>, 1990；Baer and Chen, <em>ISCA</em>, 1991。</li></ul>',9))])}const C=l(h,[["render",m]]);export{B as __pageData,C as default};
